function Stage-ProVolumeRetirement($Session,$Meta,$Guard,[string]$ScriptDirectory){
 $source=Join-Path $ScriptDirectory 'pro-volume-retire.mjs';$Guard.PinInputFile($source);$hash=(Get-FileHash $source).Hash.ToLowerInvariant();$target='C:\MuLab\approved\volume-'+$Meta.caseId+'-retire-'+$hash.Substring(0,16)+'.mjs';Copy-Item -LiteralPath $source -Destination $target -ToSession $Session
 return Invoke-Command -Session $Session -ArgumentList $Meta.caseId,$target,$hash -ScriptBlock {
  param($caseId,$target,$hash)
  $ErrorActionPreference='Stop';$prefix='C:\MuLab\approved\volume-'+$caseId;$file=$prefix+'-config.json';$cfg=[IO.File]::ReadAllText($file)|ConvertFrom-Json;$receipt=[IO.File]::ReadAllText($prefix+'-preserved.json')|ConvertFrom-Json;$failed=[IO.File]::ReadAllText($prefix+'-recover-result.json')|ConvertFrom-Json
  if(-not $receipt.complete -or $receipt.caseId -ne $caseId -or $receipt.id -ne $failed.nested.id -or -not $receipt.retirementAllowed -or $failed.complete -ne $false -or -not $failed.processExitConfirmed -or -not $failed.brokerExitConfirmed -or $receipt.archive -ne ('C:\MuLab\private\volume-'+$caseId+'-failed-original') -or (Get-FileHash $target).Hash.ToLowerInvariant() -ne $hash){throw 'Verified preserved failure required before explicit retirement'}
  if(@(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -eq $cfg.node -and $_.CommandLine -like ('*'+$caseId+'*')) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe'}).Count -or [string](Get-VM -Id ([guid]$receipt.platformId)).State -ne 'Off'){throw 'Failure is not terminal and stopped'}
  $disk=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$cfg.userSid+'/vms/'+$receipt.id+'/disk.vhdx');foreach($path in @($disk,(Join-Path $receipt.archive 'disk.vhdx'))){if((Get-FileHash $path).Hash.ToLowerInvariant() -ne $receipt.originalDiskSha256){throw 'Archive or original failed disk changed'}}
  $cfg|Add-Member -NotePropertyName retireClient -NotePropertyValue $target -Force;$cfg|Add-Member -NotePropertyName retireClientSha256 -NotePropertyValue $hash -Force;[IO.File]::WriteAllText($file,($cfg|ConvertTo-Json -Depth 16),[Text.UTF8Encoding]::new($false));$approval=@{complete=$true;caseId=$caseId;id=$receipt.id;platformId=$receipt.platformId;archiveVerified=$true};[IO.File]::WriteAllText(($prefix+'-retire-approved.json'),($approval|ConvertTo-Json),[Text.UTF8Encoding]::new($false));return $approval
 }
}
